{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C03"],
      "claim": "Vismodegib, which shares the 4-methylsulfonylphenyl motif and a chloroaromatic ring, has a measured absolute bioavailability of 31.8% in healthy subjects after a 150 mg oral dose, supporting F >= 20% for the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C11"],
      "claim": "Rofecoxib, containing the same methylsulfonylphenyl group attached to a heterocycle, shows approximately 93% oral bioavailability in healthy volunteers, indicating that this sulfone-containing scaffold is well absorbed.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C24"],
      "claim": "Valdecoxib, a sulfonamide analogue with a similar para-substituted phenyl-heteroaryl core, has an absolute bioavailability of 83% in humans, supporting high oral absorption for the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C04"],
      "claim": "Esaxerenone, which contains a methylsulfonylphenyl group, has an absolute bioavailability of 89.0% in the fasting state in healthy subjects, directly matching the fasted condition of the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C25"],
      "claim": "5-Hydroxyrofecoxib, a more polar hydroxylated metabolite of rofecoxib, has low absolute bioavailability (~14-15%) in humans; however, its extra hydroxyl/lactol polarity reduces transferability to the query.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "The query's 4-methylsulfonylphenyl heteroaryl scaffold is closely mirrored by several orally bioavailable drugs with direct human absolute-bioavailability measurements: vismodegib 31.8%, rofecoxib ~93%, valdecoxib 83%, and esaxerenone 89% in the fasting state. These consistently support F >= 20%; the only low-F analogue is a more polar hydroxylated metabolite with limited transferability. Therefore the query is predicted to have high oral bioavailability at the F >= 20% threshold.",
  "evidence_gaps": [
    "No direct experimental bioavailability data exist for the query molecule.",
    "All evidence comes from analogues with moderate Morgan similarity (0.22-0.28).",
    "The query's exact solubility, permeability, and first-pass metabolism are uncharacterized.",
    "Fasted-state absolute bioavailability data are available only for esaxerenone among the closest analogues."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

